class Solution {
public:
    string convert(string s, int numRows) {
        if (numRows == 1 || numRows >= (int)s.size()) return s;
        int n = s.size();
        vector<vector<char>> grid(numRows, vector<char>(n, 0));
        int row = 0, col = 0;
        bool going_down = true;
        for (char ch : s) {
            grid[row][col] = ch;
            if (row == 0) going_down = true;
            else if (row == numRows - 1) going_down = false;
            if (going_down) row++;
            else { row--; col++; }
        }
        string res;
        res.reserve(n);
        for (int r = 0; r < numRows; ++r)
            for (int c = 0; c < n; ++c)
                if (grid[r][c] != 0) res.push_back(grid[r][c]);
        return res;
    }
};

