class Solution:
    def convert(self, s: str, numRows: int) -> str:
        if numRows == 1 or numRows >= len(s):
            return s
        n = len(s)
        grid = [[''] * n for _ in range(numRows)]
        row, col = 0, 0
        going_down = True
        for ch in s:
            grid[row][col] = ch
            if row == 0:
                going_down = True
            elif row == numRows - 1:
                going_down = False
            if going_down:
                row += 1
            else:
                row -= 1
                col += 1
        res = []
        for r in range(numRows):
            for c in range(n):
                if grid[r][c] != '':
                    res.append(grid[r][c])
        return ''.join(res)

